class Editor {
  #state = { text: '', caret: 0 };
  #history = [];                        // caretaker
  save() { this.#history.push(structuredClone(this.#state)); }
  undo() { const s = this.#history.pop(); if (s) this.#state = s; }
  setText(text) { this.save(); this.#state = { ...this.#state, text }; }
}

