const frozen = s => Object.freeze({ ...s });

let state = frozen({ text: '', caret: 0 });
const history = [];                    // caretaker
function setText(text) {
  history.push(state);                 // previous immutable state == memento
  state = frozen({ ...state, text });
}
function undo() { state = history.pop() ?? state; }
